<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Digital I/O Registers - SLAU208Q</title>
<script type="text/javascript" id="MathJax-script" async
  src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js">
</script>
<style>
  body {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 14px;
    color: #000;
    margin: 0;
    padding: 40px 60px;
    position: relative;
  }
  .header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    border-bottom: 2px solid #000;
    padding-bottom: 6px;
    margin-bottom: 4px;
  }
  .header .left-title {
    font-style: italic;
    font-size: 15px;
  }
  .header .right-url {
    font-size: 14px;
  }
  .logo {
    text-align: right;
  }
  .logo img {
    height: 50px;
  }
  .top-bar {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: 10px;
  }
  .ti-logo {
    font-weight: bold;
    font-size: 22px;
    display: flex;
    align-items: center;
    gap: 6px;
  }
  .ti-logo .ti-box {
    background: #000;
    color: #fff;
    padding: 2px 8px;
    font-style: italic;
    font-size: 20px;
  }
