    border-collapse: collapse;
  }
  .note-block td {
    vertical-align: top;
    padding: 0;
  }
  .note-label {
    font-weight: bold;
    padding-right: 15px;
    white-space: nowrap;
  }
  .table-title {
    text-align: center;
    font-weight: bold;
    font-size: 16px;
    margin-bottom: 10px;
  }
  table.reg-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
  }
  table.reg-table thead tr {
    background-color: #d9d9d9;
  }
