<body>

  <div class="top-bar">
    <div style="width:60%;"></div>
    <div class="ti-logo">
      <div class="ti-box">ti</div>
      <div class="ti-logo-text">TEXAS<br>INSTRUMENTS</div>
    </div>
  </div>

  <div class="header">
    <div class="left-title">Digital I/O Registers</div>
    <div class="right-url">www.ti.com</div>
  </div>

  <h1 class="section-title">12.4&nbsp;&nbsp;Digital I/O Registers</h1>

  <p class="intro">
    The digital I/O registers are listed in <a href="#">Table 12-2</a>. The base addresses can be found in the device-specific
    data sheet. Each port grouping begins at its base address. The address offsets are given in <a href="#">Table 12-2</a>.
  </p>

  <div class="note-block">
    <table>
      <tr>
        <td class="note-label">NOTE:</td>
        <td>
          All registers have word or byte register access. For a generic register <em>ANYREG</em>, the suffix
          "_L" (<em>ANYREG_L</em>) refers to the lower byte of the register (bits 0 through 7). The suffix "_H"
          (<em>ANYREG_H</em>) refers to the upper byte of the register (bits 8 through 15).
        </td>
      </tr>
    </table>
  </div>

  <div class="table-title">Table 12-2. Digital I/O Registers</div>

  <table class="reg-table">
    <thead>
      <tr>
        <th style="width:8%;">Offset</th>
        <th style="width:12%;">Acronym</th>
        <th style="width:28%;">Register Name</th>
        <th style="width:11%;">Type</th>
        <th style="width:10%;">Access</th>
        <th style="width:9%;">Reset</th>
        <th style="width:12%;">Section</th>
      </tr>
    </thead>
    <tbody>
      <tr class="group-start"><td>0Eh</td><td>P1IV</td><td>Port 1 Interrupt Vector</td><td>Read only</td><td>Word</td><td>0000h</td><td><a href="#">Section 12.4.1</a></td></tr>
      <tr><td>0Eh</td><td>P1IV_L</td><td></td><td>Read only</td><td>Byte</td><td>00h</td><td></td></tr>
      <tr><td>0Fh</td><td>P1IV_H</td><td></td><td>Read only</td><td>Byte</td><td>00h</td><td></td></tr>

      <tr class="group-start"><td>1Eh</td><td>P2IV</td><td>Port 2 Interrupt Vector</td><td>Read only</td><td>Word</td><td>0000h</td><td><a href="#">Section 12.4.2</a></td></tr>
      <tr><td>1Eh</td><td>P2IV_L</td><td></td><td>Read only</td><td>Byte</td><td>00h</td><td></td></tr>
      <tr><td>1Fh</td><td>P2IV_H</td><td></td><td>Read only</td><td>Byte</td><td>00h</td><td></td></tr>

      <tr class="group-start"><td>00h</td><td>P1IN or<br>PAIN_L</td><td>Port 1 Input</td><td>Read only</td><td>Byte</td><td></td><td><a href="#">Section 12.4.9</a></td></tr>
      <tr><td>02h</td><td>P1OUT or<br>PAOUT_L</td><td>Port 1 Output</td><td>Read/write</td><td>Byte</td><td>undefined</td><td><a href="#">Section 12.4.10</a></td></tr>
      <tr><td>04h</td><td>P1DIR or<br>PADIR_L</td><td>Port 1 Direction</td><td>Read/write</td><td>Byte</td><td>00h</td><td><a href="#">Section 12.4.11</a></td></tr>
      <tr><td>06h</td><td>P1REN or<br>PAREN_L</td><td>Port 1 Resistor Enable</td><td>Read/write</td><td>Byte</td><td>00h</td><td><a href="#">Section 12.4.12</a></td></tr>
      <tr><td>08h</td><td>P1DS or<br>PADS_L</td><td>Port 1 Drive Strength</td><td>Read/write</td><td>Byte</td><td>00h</td><td><a href="#">Section 12.4.13</a></td></tr>
      <tr><td>0Ah</td><td>P1SEL or<br>PASEL_L</td><td>Port 1 Port Select</td><td>Read/write</td><td>Byte</td><td>00h</td><td><a href="#">Section 12.4.14</a></td></tr>
      <tr><td>18h</td><td>P1IES or<br>PAIES_L</td><td>Port 1 Interrupt Edge Select</td><td>Read/write</td><td>Byte</td><td>undefined</td><td><a href="#">Section 12.4.3</a></td></tr>
      <tr><td>1Ah</td><td>P1IE or<br>PAIE_L</td><td>Port 1 Interrupt Enable</td><td>Read/write</td><td>Byte</td><td>00h</td><td><a href="#">Section 12.4.4</a></td></tr>
      <tr><td>1Ch</td><td>P1IFG or<br>PAIFG_L</td><td>Port 1 Interrupt Flag</td><td>Read/write</td><td>Byte</td><td>00h</td><td><a href="#">Section 12.4.5</a></td></tr>

      <tr class="group-start"><td>01h</td><td>P2IN or<br>PAIN_H</td><td>Port 2 Input</td><td>Read only</td><td>Byte</td><td></td><td><a href="#">Section 12.4.9</a></td></tr>
      <tr><td>03h</td><td>P2OUT or<br>PAOUT_H</td><td>Port 2 Output</td><td>Read/write</td><td>Byte</td><td>undefined</td><td><a href="#">Section 12.4.10</a></td></tr>
      <tr><td>05h</td><td>P2DIR or<br>PADIR_H</td><td>Port 2 Direction</td><td>Read/write</td><td>Byte</td><td>00h</td><td><a href="#">Section 12.4.11</a></td></tr>
      <tr><td>07h</td><td>P2REN or<br>PAREN_H</td><td>Port 2 Resistor Enable</td><td>Read/write</td><td>Byte</td><td>00h</td><td><a href="#">Section 12.4.12</a></td></tr>
      <tr><td>09h</td><td>P2DS or<br>PADS_H</td><td>Port 2 Drive Strength</td><td>Read/write</td><td>Byte</td><td>00h</td><td><a href="#">Section 12.4.13</a></td></tr>
      <tr><td>0Bh</td><td>P2SEL or<br>PASEL_H</td><td>Port 2 Port Select</td><td>Read/write</td><td>Byte</td><td>00h</td><td><a href="#">Section 12.4.14</a></td></tr>
      <tr><td>19h</td><td>P2IES or<br>PAIES_H</td><td>Port 2 Interrupt Edge Select</td><td>Read/write</td><td>Byte</td><td>undefined</td><td><a href="#">Section 12.4.6</a></td></tr>
      <tr><td>1Bh</td><td>P2IE or<br>PAIE_H</td><td>Port 2 Interrupt Enable</td><td>Read/write</td><td>Byte</td><td>00h</td><td><a href="#">Section 12.4.7</a></td></tr>
      <tr><td>1Dh</td><td>P2IFG or<br>PAIFG_H</td><td>Port 2 Interrupt Flag</td><td>Read/write</td><td>Byte</td><td>00h</td><td><a href="#">Section 12.4.8</a></td></tr>

      <tr class="group-start"><td>00h</td><td>P3IN or<br>PBIN_L</td><td>Port 3 Input</td><td>Read only</td><td>Byte</td><td></td><td><a href="#">Section 12.4.9</a></td></tr>
      <tr><td>02h</td><td>P3OUT or<br>PBOUT_L</td><td>Port 3 Output</td><td>Read/write</td><td>Byte</td><td>undefined</td><td><a href="#">Section 12.4.10</a></td></tr>
    </tbody>
  </table>

  <div class="footer">
    <div class="left">416&nbsp;&nbsp;<em>Digital I/O Module</em></div>
    <div class="right">
      SLAU208Q&nbsp;–&nbsp;June 2008&nbsp;–&nbsp;Revised March 2018<br>
      <a href="#">Submit Documentation Feedback</a>
    </div>
  </div>
  <div class="copyright">Copyright &copy; 2008–2018, Texas Instruments Incorporated</div>

</body>
</html>
